import java.util.*;

class Solution {
  public int findMaxLength(int[] nums) {
    Map<Integer, Integer> first = new HashMap<>(); // balance (+1 for 1, -1 for 0) -> earliest index
    first.put(0, -1);
    int balance = 0, best = 0;
    for (int i = 0; i < nums.length; i++) {
      balance += nums[i] == 1 ? 1 : -1;
      Integer prev = first.putIfAbsent(balance, i);
      if (prev != null) best = Math.max(best, i - prev);
    }
    return best;
  }
}
